/** Actual native cog ratio/reversal, lever/clutch off transition and staged OP2confirmation. */
final class CreateTransmissionRuntime {
 static final BlockPos CENTER=new BlockPos(512,85,512),LARGE=CENTER.north(2),SMALL=LARGE.east().above(),CLUTCH=CENTER.south(),OUTPUT=CLUTCH.south(),LEVER=CLUTCH.above(),EXTRA=SMALL.south().above();
 static void run(GameTestHelper h,Runnable done)throws Exception{
  var level=h.getLevel();var server=level.getServer();var id=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().equals(BlueprintRegistry.HUT)).findFirst().orElseThrow().owner();var actor=server.getPlayerList().getPlayer(id);if(actor==null)actor=ClaimRuntimeTests.vanillaPlayer(level,id,"HallOwner");final var p=actor;server.getPlayerList().deop(p.getGameProfile());var track=CommerceService.store(server).professions(id).track(Profession.ENGINEER);h.assertTrue(track.completedQuestIds().contains(MillingService.QUEST),"Use the actually earned six Apprentice/native milling source");
  for(int x=31;x<=32;x++)for(int z=31;z<=32;z++){level.getChunk(x,z);var at=new BlockPos(x*16,85,z*16);ClaimRuntimeTests.ftbUnclaim(level,at);ClaimRuntimeTests.ftbClaim(p,at);ClaimRuntimeTests.opacUnclaim(level,at);ClaimRuntimeTests.opacClaim(level,id,at);}BlacksmithRepairRuntime.near(p,CENTER);
  if(track.completedQuestIds().contains(CreateTransmissionInspection.QUEST)){server.tickRateManager().setTickRate(20);h.runAfterDelay(80,()->{try{h.assertTrue(track.xp()==700&&track.completedQuestIds().size()==7&&level.getBlockState(CLUTCH).getValue(BlockStateProperties.POWERED)&&((Number)CreateDriveRuntime.number(level.getBlockEntity(OUTPUT),"getSpeed")).floatValue()==0&&((Number)CreateDriveRuntime.number(level.getBlockEntity(LARGE),"getSpeed")).floatValue()!=0,"Actual second JVM restores stopped selected output, live geartrain and7earned700XP; final assessment still required");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("CREATE_TRANSMISSION_RESTART_PASSED: actual native powered/clutched-off output and live ratio/reversal/7earned700XP/audit/original Workshop-Ivo persist without replay or rank fabrication");done.run();}catch(Exception failure){h.fail(failure.toString());}});return;}
  h.assertTrue(track.xp()==600&&track.completedQuestIds().size()==6,"Starts with actual six prior native proofs/600XP");boolean refused=false;try{CreateTransmissionInspection.capture(p,CENTER);}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused,"A live wheel alone cannot replace three mechanical functions");build(h,p);
  h.runAfterDelay(160,()->{try{
   var frame=CreateTransmissionInspection.capture(p,CENTER);h.assertTrue(frame.lever().equals(LEVER)&&frame.output().equals(OUTPUT)&&Math.abs(frame.speedA())!=Math.abs(frame.speedB())&&Math.signum(frame.speedA())!=Math.signum(frame.speedB()),"Actual native connected same-axis cog ratio/reversal and live clutch output captured, without assigned speeds/networks");
   var adminId=ConstructionService.store(server).projects().stream().filter(q->ProfessionPremises.contains(q.blueprint())).findFirst().orElseThrow().owner();var admin=server.getPlayerList().getPlayer(adminId);h.assertTrue(admin!=null&&!adminId.equals(id),"Original independent owner attends as operator");server.getPlayerList().op(admin.getGameProfile());admin.moveTo(CENTER.getX()+2.5,CENTER.getY()+1,CENTER.getZ()-2.5);p.moveTo(CENTER.getX()+.5,CENTER.getY(),CENTER.getZ()-2.5);
   var first=ProfessionInspectionService.review(admin,p,CreateTransmissionInspection.QUEST,CENTER,"Inspected genuine ratio reversal and safe controllable output with current owner consent");boolean denied=false;try{ProfessionInspectionService.confirm(admin,first);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied&&CommerceService.store(server).professions(id).track(Profession.ENGINEER).xp()==600,"Confirming while output still turns refuses approval/XP");staged(h,p,admin,frame,0,done);
  }catch(Exception failure){h.fail("Native transmission: "+failure+" large="+CreateDriveRuntime.number(level.getBlockEntity(LARGE),"getSpeed")+" small="+CreateDriveRuntime.number(level.getBlockEntity(SMALL),"getSpeed")+" clutch="+CreateDriveRuntime.number(level.getBlockEntity(CLUTCH),"getSpeed")+" output="+CreateDriveRuntime.number(level.getBlockEntity(OUTPUT),"getSpeed"));}});
 }
 static void staged(GameTestHelper h,ServerPlayer p,ServerPlayer admin,CreateTransmissionInspection.Running frame,int stage,Runnable done)throws Exception{
  var server=p.server;var level=p.serverLevel();admin.moveTo(CENTER.getX()+2.5,CENTER.getY()+1,CENTER.getZ()-2.5);p.moveTo(CENTER.getX()+.5,CENTER.getY(),CENTER.getZ()-2.5);var review=ProfessionInspectionService.review(admin,p,CreateTransmissionInspection.QUEST,CENTER,"Inspected genuine ratio reversal and safe controllable output with current owner consent");toggle(h,p,LEVER,true);if(stage==0)toggle(h,p,EXTRA,true);
  h.runAfterDelay(80,()->{try{
   CreateTransmissionInspection.stopped(p,frame);if(stage==1){ClaimRuntimeTests.ftbUnclaim(level,CENTER);ClaimRuntimeTests.ftbClaim(admin,CENTER);}boolean denied=false;try{ProfessionInspectionService.confirm(admin,review);}catch(IllegalStateException expected){denied=true;}
   if(stage<2){h.assertTrue(denied&&CommerceService.store(server).professions(p.getUUID()).track(Profession.ENGINEER).xp()==600,stage==0?"Unrelated real lever change remains in geometry snapshot; selected power-bit allowance cannot hide it":"After-review actual FTBclaim revocation denies staged approval despite genuine stopped output");if(stage==1){ClaimRuntimeTests.ftbUnclaim(level,CENTER);ClaimRuntimeTests.ftbClaim(p,CENTER);}if(stage==0)toggle(h,p,EXTRA,false);toggle(h,p,LEVER,false);h.runAfterDelay(80,()->{try{staged(h,p,admin,frame,stage+1,done);}catch(Exception failure){server.getPlayerList().deop(admin.getGameProfile());h.fail(failure.toString());}});return;}
   h.assertTrue(!denied,"Unchanged approved site and genuine controlled shutoff confirm successfully");var earned=CommerceService.store(server).professions(p.getUUID()).track(Profession.ENGINEER);h.assertTrue(earned.xp()==700&&earned.completedQuestIds().size()==7,"Actual staged live-to-stopped native demonstration earns100XPonce, final workshop remains closed");boolean duplicate=false;try{ProfessionInspectionService.confirm(admin,review);}catch(IllegalStateException expected){duplicate=true;}h.assertTrue(duplicate,"Same staged confirmation cannot repeat XP");CommerceService.verifyReceipt(p);h.assertTrue(EconomyStore.open(server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("data")).professions(p.getUUID()).equals(CommerceService.store(server).professions(p.getUUID())),"Canonical control/geometry audit and earned records reopen");server.getPlayerList().deop(admin.getGameProfile());com.mojang.logging.LogUtils.getLogger().info("CREATE_TRANSMISSION_NATIVE_PASSED: real consumed gear/clutch/lever/shaft placements and actual fluid-native ratio/reversal, running-output confirmation refusal, genuine lever native shutoff with upstream gearing live, unrelated-control geometry and current FTBrevocation refuse, OP2staged confirmation/7earned700XP/no duplicate; private raw supplies/tier/time only");done.run();
  }catch(Exception failure){server.getPlayerList().deop(admin.getGameProfile());h.fail("Actual native shutoff stage "+stage+": "+failure);}});
 }
 static void build(GameTestHelper h,ServerPlayer p){var level=p.serverLevel();for(var at:List.of(LARGE,SMALL,CLUTCH,OUTPUT,LEVER))h.assertTrue(level.getBlockState(at).isAir()||!level.getBlockState(at).getFluidState().isEmpty(),"Native training additions use only clear/replaceable private fluid cells, never existing buildings");CreateDriveRuntime.place(h,p,LARGE,new ItemStack(CreateCraftRuntime.item("create:large_cogwheel")),LARGE.south(),Direction.NORTH);var support=SMALL.below();CreateDriveRuntime.place(h,p,support,new ItemStack(Items.STONE),support.below(),Direction.UP);var backing=SMALL.south();CreateDriveRuntime.place(h,p,backing.below(),new ItemStack(Items.STONE),backing.below(2),Direction.UP);CreateDriveRuntime.place(h,p,backing,new ItemStack(Items.STONE),backing.below(),Direction.UP);CreateDriveRuntime.place(h,p,SMALL,new ItemStack(CreateCraftRuntime.item("create:cogwheel")),backing,Direction.NORTH);CreateDriveRuntime.place(h,p,CLUTCH,new ItemStack(CreateCraftRuntime.item("create:clutch")),CENTER,Direction.SOUTH);CreateDriveRuntime.place(h,p,OUTPUT,new ItemStack(CreateCraftRuntime.item("create:shaft")),CLUTCH,Direction.SOUTH);CreateDriveRuntime.place(h,p,LEVER,new ItemStack(Items.LEVER),CLUTCH,Direction.UP);CreateDriveRuntime.place(h,p,EXTRA,new ItemStack(Items.LEVER),EXTRA.below(),Direction.UP);}
 static void toggle(GameTestHelper h,ServerPlayer p,BlockPos at,boolean powered){var level=p.serverLevel();var held=p.getMainHandItem().copy();BlacksmithRepairRuntime.near(p,at);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);var result=p.gameMode.useItemOn(p,level,p.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at),Direction.UP,at,false));p.setItemInHand(InteractionHand.MAIN_HAND,held);h.assertTrue(result.consumesAction()&&level.getBlockState(at).getValue(BlockStateProperties.POWERED)==powered,"Actual permitted survival lever use changes native redstone control");}
}
